def transform(grid):
    h,w=len(grid),len(grid[0]); g=[row[:] for row in grid]
    seen=set(); comps=[]; labels=[[-1]*w for _ in range(h)]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0 and (r,c) not in seen:
          q=[(r,c)]; seen.add((r,c)); cells=[]
          for y,x in q:
            cells.append((y,x));
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              yy,xx=y+dy,x+dx
              if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
                seen.add((yy,xx)); q.append((yy,xx))
          k=len(comps); comps.append(cells)
          for y,x in cells: labels[y][x]=k
    colors={}
    for k,cells in enumerate(comps):
      cs={grid[y][x] for y,x in cells if grid[y][x]>1}
      if cs: colors[k]=min(cs)
    for r in range(1,h-1):
      for c in range(1,w-1):
        if all(grid[y][x]!=0 for y in range(r-1,r+2) for x in range(c-1,c+2)):
          k=labels[r][c]
